    checks: list[CheckSpec],
    *,
    reflection_keyed_types: frozenset[str],
    normalize_name: Callable[[str], str],
) -> list[CheckSpec]:
    """Fold `column_list` on every check whose GX metric indexes REFLECTED columns —
    ``normalize_name`` should be the target dialect's own reflection rewrite, so an
    all-caps authored spelling matches the reflected (often lower-cased) key instead of
    KeyError-ing live-only (#1616 Snowflake, #1624 Databricks).
    """
    folded = []
    for spec in checks:
        column_list = spec.kwargs.get("column_list")
        if spec.expectation_type in reflection_keyed_types and isinstance(column_list, list):
            spec = CheckSpec(
                expectation_type=spec.expectation_type,
                kwargs={
                    **spec.kwargs,
                    "column_list": [
                        normalize_name(c) if isinstance(c, str) else c for c in column_list
                    ],
                },
            )
        folded.append(spec)
    return folded


